-- Données de DÉMONSTRATION de la qualification (spec 024) — ENTIÈREMENT FICTIVES.
-- Chargées par deploy/demo-qualif.ps1 (local ou preview, JAMAIS la production). Comptes en
-- @demo.test (domaine réservé), photos = illustrations dessinées (app/src/db/demo/*.svg rendues
-- en JPEG). Dates relatives au jour du chargement. Relançable : tout ce qui est rattaché aux
-- comptes @demo.test est d'abord supprimé (et les mentions « fait par » de ces comptes effacées).
-- Les deux longues lignes base64 sont les illustrations ; le reste se modifie à la main.

-- 1. Nettoyage d'un chargement précédent
DELETE FROM paiements WHERE saisi_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test')
  OR id IN (SELECT paiement_id FROM paiement_parts WHERE adhesion_id IN (SELECT id FROM adhesions WHERE adherent_id IN (SELECT adherent_id FROM liens WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test') UNION SELECT id FROM adherents WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test') OR propose_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test'))));
DELETE FROM competitions WHERE cree_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
DELETE FROM inscriptions_competition WHERE adherent_id IN (SELECT adherent_id FROM liens WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test') UNION SELECT id FROM adherents WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test') OR propose_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test')) OR inscrit_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
DELETE FROM inscriptions_famille WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
DELETE FROM garderie_demandes WHERE adherent_id IN (SELECT adherent_id FROM liens WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test') UNION SELECT id FROM adherents WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test') OR propose_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test')) OR demande_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
UPDATE garderie_demandes SET pointe_par = NULL WHERE pointe_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
UPDATE garderie_demandes SET parti_par = NULL WHERE parti_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
DELETE FROM photos_adherents WHERE adherent_id IN (SELECT adherent_id FROM liens WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test') UNION SELECT id FROM adherents WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test') OR propose_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test'));
