DELETE FROM actualites WHERE auteur IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
UPDATE actualites_images SET deposee_par = NULL WHERE deposee_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
DELETE FROM adhesions WHERE adherent_id IN (SELECT adherent_id FROM liens WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test') UNION SELECT id FROM adherents WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test') OR propose_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test'));
