UPDATE adhesions SET cree_par = NULL WHERE cree_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
UPDATE adhesions SET formalite_par = NULL WHERE formalite_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
UPDATE adhesions SET engagements_par = NULL WHERE engagements_par IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
