DELETE FROM journal_acces WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
DELETE FROM sessions WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
DELETE FROM liens_connexion WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@demo.test');
